{
  "summary": "The reader has an undergraduate computer science education: discrete mathematics (sets, functions, permutations, modular arithmetic, primes and gcd), calculus-level analysis (limits, sums, Newton's method), first-course linear algebra (matrices, inverses, Gaussian elimination, vectors) and complex numbers up to roots of unity, algorithm analysis (recursion, recurrences, big-O with its relatives Omega, Theta, little-o) and basic Turing machines. The reader knows binary representation and bitwise operations, and the textbook schoolbook multiplication. The reader has not studied abstract algebra beyond what the existing concepts introduce (rings and quotient rings, zero divisors, group characters), number-theory estimates on primes, numerical analysis of rounding errors, fast multiplication algorithms beyond the basics, or any coding-theory or quantum-computing notation, so those are explained in the wiki.",
  "known": [
    {
      "name": "Asymptotic notation beyond big-O",
      "aliases": ["Omega", "Theta", "little-o", "Ω(f)", "Θ(f)", "o(f)", "liminf", "limit of a ratio", "asymptotic lower bound", "asymptotic equivalence"],
      "gloss": "Ω gives an asymptotic lower bound, Θ means both O and Ω, and o(f) means the ratio to f tends to zero, all stated for n large enough."
    },
    {
      "name": "Logarithms, exponentials, floor and ceiling",
      "aliases": ["lg", "log base 2", "log2", "natural logarithm", "ln", "floor", "ceiling", "⌊x⌋", "⌈x⌉", "powers of two", "iterated logarithm"],
      "gloss": "The base-2 and natural logarithms as inverses of exponentials, their growth rates relative to powers of n, and rounding down or up to an integer."
    },
    {
      "name": "Binary representation and bitwise operations",
      "aliases": ["binary numbers", "positional notation", "radix representation", "base-b digits", "most significant bit", "bit string", "XOR", "exclusive or", "bitwise addition mod 2", "two's complement", "leading zeroes", "carry"],
      "gloss": "An integer written in a positional base as digits or bits with a most significant end, with addition by carries, bitwise XOR as addition mod 2, and signed words in two's complement."
    },
    {
      "name": "Schoolbook integer arithmetic",
      "aliases": ["grade-school multiplication", "long multiplication", "long division", "quadratic-time multiplication", "integer division with remainder", "quotient and remainder", "Euclidean division"],
      "gloss": "Digit-by-digit addition, multiplication and division with remainder, with the quadratic cost of schoolbook multiplication on n-digit numbers."
    },
    {
      "name": "Modular arithmetic",
      "aliases": ["congruence", "residues", "mod q", "integers modulo n", "ℤ/qℤ", "units modulo q", "modular inverse", "multiplicative inverse mod q", "residue ring"],
      "gloss": "Arithmetic on integers with equality taken up to multiples of a modulus, where the elements coprime to the modulus have multiplicative inverses."
    },
    {
      "name": "Primes, coprimality and gcd",
      "aliases": ["prime numbers", "pairwise coprime", "relatively prime", "greatest common divisor", "gcd", "extended Euclidean algorithm", "Euclid's algorithm", "trial division", "odd prime", "divisibility", "prime to q"],
      "gloss": "Primes and divisibility, greatest common divisors and Bezout coefficients via the extended Euclidean algorithm, and finding primes by trial division."
    },
    {
      "name": "Sets, functions, Cartesian products and bijections",
      "aliases": ["index set", "[n] = {0,...,n-1}", "product set", "Cartesian product", "injective surjective bijective", "inverse map", "indexing", "lexicographic order", "mixed-radix index"],
      "gloss": "Finite sets and index ranges, tuples and Cartesian products, functions, bijections and their inverses, and lexicographic ordering of tuples."
    },
    {
      "name": "Permutations",
      "aliases": ["permutation of positions", "bit-reversal permutation", "involution", "composition of permutations", "permutation matrix", "cyclic shift", "swap", "partial permutation"],
      "gloss": "A bijection of a finite set onto itself, composed like functions, including swaps, cyclic shifts and permutation matrices."
    },
    {
      "name": "Matrices and linear maps",
      "aliases": ["matrix multiplication", "identity matrix", "invertible matrix", "matrix inverse", "transpose", "matrix transposition", "Gaussian elimination", "row operations", "linear operator", "diagonal matrix", "lower triangular matrix", "GL(m)", "row-major order", "linearity"],
      "gloss": "Matrices acting on vectors as linear maps, with products, inverses, transposes, triangular and diagonal forms, and row reduction by Gaussian elimination."
    },
    {
      "name": "Roots of unity",
      "aliases": ["nth roots of unity", "primitive root of unity", "e^{2πi/n}", "character sum", "sum of roots of unity vanishes", "geometric sum of roots of unity"],
      "gloss": "The n complex solutions of z^n = 1, equally spaced on the unit circle, whose powers sum to zero unless the power is a multiple of n."
    },
    {
      "name": "Summation, geometric series and products",
      "aliases": ["sigma notation", "geometric sum", "geometric series", "arithmetic series", "sum of a geometric progression", "product notation", "telescoping sum", "telescoping"],
      "gloss": "Finite sums and products in sigma and pi notation, closed forms for geometric progressions, and telescoping cancellation."
    },
    {
      "name": "Recursion and divide-and-conquer recurrences",
      "aliases": ["recurrence relation", "master theorem", "recursion depth", "solving recurrences", "recursive call", "unrolling a recurrence", "divide and conquer"],
      "gloss": "Algorithms that call themselves on smaller inputs, with cost expressed by a recurrence such as T(n) = aT(n/b) + f(n) and bounded by unrolling or the master theorem."
    },
    {
      "name": "Worst-case running time and subroutines",
      "aliases": ["deterministic algorithm", "worst-case time", "black box", "subroutine call", "reduction", "time complexity", "exact computation", "bit complexity", "depth-first schedule"],
      "gloss": "A deterministic algorithm's cost is the maximum number of steps over inputs of a given size, and a reduction solves one problem by calling a procedure for another."
    },
    {
      "name": "Triangle inequality and norms",
      "aliases": ["triangle inequality", "absolute value of a sum", "max norm", "sup norm", "operator norm", "|z+w| ≤ |z|+|w|", "error bound", "absolute error"],
      "gloss": "The modulus of a sum is at most the sum of moduli, used to bound the size of sums and the accumulation of errors."
    },
    {
      "name": "Rational numbers and rounding",
      "aliases": ["fractions", "dyadic rational", "rounding to nearest integer", "truncation toward zero", "denominator", "reals", "real and imaginary parts"],
      "gloss": "Fractions with integer numerator and denominator, with rounding of a real number to the nearest integer or toward zero."
    },
    {
      "name": "Newton's method",
      "aliases": ["Newton iteration", "Newton-Raphson", "quadratic convergence", "reciprocal iteration", "square root iteration"],
      "gloss": "The iteration x ↦ x − f(x)/f'(x) for approximating a root, which roughly doubles the number of correct digits per step."
    },
    {
      "name": "Tapes, scanning and sorting as basic machine procedures",
      "aliases": ["scan a tape", "linear scan", "copying a tape", "merge", "sorting", "work tape", "head movement", "tape reversal"],
      "gloss": "Standard machine-level procedures such as one left-to-right scan, copying between tapes, and merging or sorting lists."
    }
  ]
}
EOF
python3 -m json.tool exegenius/tasks/0002-background.answer.json >/dev/null && exegenius submit 0002-background

